import java.util.*;
import java.io.*;

public class Main {
    static final int N = 12, INF = 1000000009;
    static final int[] dx = {0, 1, 0, -1};
    static final int[] dy = {1, 0, -1, 0};
    static int n, t;
    static char[][] grid1 = new char[N][N];
    static char[][] grid2 = new char[N][N];
    static int start_row, start_col;
    static int[][] dist_map = new int[N][N];

    static class Coord {
        int r, c;
        Coord(int _r, int _c) {
            r = _r;
            c = _c;
        }
    }

    static void run_search(int[][] dist_map, int sr, int sc) {
        boolean[][] visited = new boolean[N][N];
        for (int i = 0; i < n; ++i)
            Arrays.fill(dist_map[i], INF);
        Queue<Coord> q = new LinkedList<>();
        visited[sr][sc] = true;
        dist_map[sr][sc] = 0;
        q.offer(new Coord(sr, sc));
        while (!q.isEmpty()) {
            Coord c = q.poll();
            for (int dir_idx = 0; dir_idx < 4; ++dir_idx) {
                int nxt_r = c.r + dx[dir_idx];
                int nxt_c = c.c + dy[dir_idx];
                if (nxt_r >= 0 && nxt_r < n && nxt_c >= 0 && nxt_c < n
                        && !visited[nxt_r][nxt_c]
                        && grid1[nxt_r][nxt_c] >= '0' && grid1[nxt_r][nxt_c] <= '9') {
                    visited[nxt_r][nxt_c] = true;
                    dist_map[nxt_r][nxt_c] = dist_map[c.r][c.c] + 1;
                    q.offer(new Coord(nxt_r, nxt_c));
                }
            }
        }
    }

    static boolean[][][][] flow_graph = new boolean[N * 6][N][N][N][N];
    static boolean[][] reachable = new boolean[N][N][N][N];

    static int[][] gmat = new int[2 * N * N][2 * N * N];

    static int[] parent_arr = new int[2 * N * N];
    static boolean[] visited_q = new boolean[2 * N * N];

    static boolean flow_bfs() {
        Arrays.fill(visited_q, false);
        Arrays.fill(parent_arr, 0);
        Queue<Integer> q = new LinkedList<>();
        visited_q[0] = true;
        q.offer(0);
        while (!q.isEmpty()) {
            int node = q.poll();
            if (node == 2 * n * n + 1)
                return true;
            for (int h = 0; h <= 2 * n * n + 1; ++h) {
                if (gmat[node][h]) {
                    if (!visited_q[h]) {
                        visited_q[h] = true;
                        parent_arr[h] = node;
                        q.offer(h);
                    }
                }
            }
        }
        return false;
    }

    static void process_input(Scanner sc) {
        n = sc.nextInt();
        t = sc.nextInt();
        for (int i = 0; i < n; ++i)
            grid1[i] = sc.next().toCharArray();
        for (int i = 0; i < n; ++i)
            grid2[i] = sc.next().toCharArray();
        start_row = sc.nextInt();
        start_col = sc.nextInt();
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if (grid1[i][j] == 'Z') {
                    start_row = i;
                    start_col = j;
                }
        run_search(dist_map, start_row, start_col);
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if ('0' <= grid1[i][j] && grid1[i][j] <= '9')
                    flow_graph[0][i][j][i][j] = true;

        for (int step = 0; step < t; ++step) {
            for (int sx = 0; sx < n; ++sx)
                for (int sy = 0; sy < n; ++sy)
                    for (int x = 0; x < n; ++x)
                        for (int y = 0; y < n; ++y) {
                            if (!flow_graph[step][sx][sy][x][y]) continue;
                            if (dist_map[x][y] <= step) continue;
                            for (int dir_idx = 0; dir_idx < 4; ++dir_idx) {
                                int hx = x + dx[dir_idx];
                                int hy = y + dy[dir_idx];
                                if (hx >= 0 && hx < n && hy >= 0 && hy < n && '0' <= grid1[hx][hy] && grid1[hx][hy] <= '9') {
                                    if (dist_map[hx][hy] >= step + 1)
                                        flow_graph[step + 1][sx][sy][hx][hy] = true;
                                }
                            }
                        }
        }
        for (int step = 0; step <= t; ++step)
            for (int sx = 0; sx < n; ++sx)
                for (int sy = 0; sy < n; ++sy)
                    for (int x = 0; x < n; ++x)
                        for (int y = 0; y < n; ++y)
                            if (flow_graph[step][sx][sy][x][y])
                                reachable[sx][sy][x][y] = true;

        for (int x1 = 0; x1 < n; ++x1)
            for (int y1 = 0; y1 < n; ++y1)
                if ('0' <= grid1[x1][y1] && grid1[x1][y1] <= '9')
                    gmat[0][x1 * n + y1 + 1] = grid1[x1][y1] - '0';

        for (int x2 = 0; x2 < n; ++x2)
            for (int y2 = 0; y2 < n; ++y2)
                if ('0' <= grid2[x2][y2] && grid2[x2][y2] <= '9')
                    gmat[n * n + x2 * n + y2 + 1][2 * n * n + 1] = grid2[x2][y2] - '0';

        for (int x1 = 0; x1 < n; ++x1)
            for (int y1 = 0; y1 < n; ++y1)
                for (int x2 = 0; x2 < n; ++x2)
                    for (int y2 = 0; y2 < n; ++y2) {
                        if (!('0' <= grid1[x1][y1] && grid1[x1][y1] <= '9')) continue;
                        if (!('0' <= grid1[x2][y2] && grid1[x2][y2] <= '9')) continue;
                        if (!reachable[x1][y1][x2][y2]) continue;
                        gmat[x1 * n + y1 + 1][n * n + x2 * n + y2 + 1] = INF;
                    }

        while (flow_bfs()) {
            int flow_amount = INF;
            for (int i = 2 * n * n + 1; i != 0; i = parent_arr[i]) {
                flow_amount = Math.min(flow_amount, gmat[parent_arr[i]][i]);
            }
            for (int i = 2 * n * n + 1; i != 0; i = parent_arr[i]) {
                gmat[parent_arr[i]][i] -= flow_amount;
                gmat[i][parent_arr[i]] += flow_amount;
            }
        }

        int total_flow = 0;
        for (int i = 0; i <= 2 * n * n + 1; ++i)
            total_flow += gmat[i][0];

        System.out.println(total_flow);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        process_input(sc);
        sc.close();
    }
}
